code_sketch:
typedef struct { int units; int loyalty; double discount; } Fact;
struct rule { const char *name; int (*when)(const Fact *); void (*then)(Fact *); int fired; };
static int  bulk(const Fact *f) { return f->units > 100 && f->loyalty > 2; }
static void apply_bulk(Fact *f)  { f->discount = 0.10; }

static struct rule rules[] = { { "volume-discount", bulk, apply_bulk, 0 } };

for (size_t i = 0; i < sizeof rules / sizeof *rules; ++i) {
    if (rules[i].fired || !rules[i].when(&fact)) continue;
    rules[i].then(&fact);   /* only actions mutate the fact */
    rules[i].fired = 1;     /* refraction: no retrigger on unchanged facts */
}

